function appearanceControls(role){const look=safeLook(config.appearance?.[role]),env=safeEnvironment(config.environment);return `<h2>この対象の見え方</h2>${!['ui','logo'].includes(role)?`<label class="check"><input type="checkbox" data-look="useColor" ${look.useColor?'checked':''} >色を指定する</label><label>色<input type="color" data-look="color" value="${look.color}"></label>`:''}<div class="transform-grid">${['background','ui','logo'].includes(role)?`<label>不透明度 / 背景の明るさ<input type="number" data-look="opacity" value="${look.opacity}" min=".05" max="1" step=".05"></label>`:''}${Object.entries({roughness:'表面のざらつき',metalness:'金属感',opacity:'不透明度',emissive:'発光',repeatX:'画像の横繰り返し',repeatY:'画像の縦繰り返し'}).filter(([k])=>!['background','ui','logo'].includes(role)&&(!['effect','water'].includes(role)||!['roughness','metalness','emissive'].includes(k)||role==='water'&&!!assets.water)).map(([k,label])=>`<label>${label}<input type="number" data-look="${k}" value="${look[k]}" min="${['repeatX','repeatY'].includes(k)?.1:k==='opacity'?.05:0}" max="${k.startsWith('repeat')?32:k==='emissive'?3:1}" step=".1"></label>`).join('')}</div><p class="fine">表面画像は水・足場・壁・水底・梁と柱・配管・照明器具・波紋ごとに独立。背景色は背景画像なしの時に反映。UI・ロゴは画像と透明度、3D素材は材質も調整できます。ゲーム判定は変わりません。</p><div class="row">${btn('見え方を保存して反映','save-look','class="primary"')}${btn('見え方を初期化','reset-look')}</div><details><summary>ステージ全体の霧・明るさ・水の動き</summary><label>霧の色<input type="color" data-env="fogColor" value="${env.fogColor}"></label>${Object.entries({fogDensity:['霧の濃さ',0,.12,.001],exposure:['画面の明るさ',.3,3,.05],light:['周囲の照明',.1,3,.1],torch:['手元ライト',0,3,.1],waterSpeed:['水面の動く速さ',0,3,.1]}).map(([k,[label,min,max,step]])=>`<label>${label}<input type="number" data-env="${k}" value="${env[k]}" min="${min}" max="${max}" step="${step}"></label>`).join('')}${btn('全体の見え方を保存','save-environment','class="primary"')}${btn('全体の見え方を初期化','reset-environment')}</details>`}
