function lockPointer(){if(!matchMedia('(pointer:fine)').matches)return;const fallback=()=>{pointerFallback=true;toast('マウスをドラッグして視点を動かせます。');const hint=root.querySelector('.controls-hint');if(hint)hint.textContent=myRole==='monster'?'WASD 移動 · ドラッグ 視点 · 水音を追え · ESC メニュー':'WASD 移動 · ドラッグ 視点 · SPACE ジャンプ · E 調べる · ESC メニュー'};try{if(!canvas.requestPointerLock){fallback();return}canvas.requestPointerLock()?.catch?.(fallback)}catch{fallback()}}
