function beginSolo(stage=import.meta.env.DEV&&new URLSearchParams(location.search).get('stage')==='2'?2:1){resultFinished=false;playType='solo';myRole='player';meId='solo';state=createMatch([createPlayer('solo')],config,undefined,[],stage);look={yaw:0,pitch:0};lastEvent=0;predicted=null;lastTick=-1;acc=0;go('instructions')}
const networkErrors={UPDATE_REQUIRED:'ゲームが更新されています。ページを再読み込みしてください。',ROOM_NOT_FOUND:'ルームが見つかりません。コードを確認してください。',ROOM_FULL:'ルームが満員です。',ALREADY_STARTED:'すでに探索が始まっています。',HOST_ONLY:'ホストだけが操作できます。',NOT_READY:'全員が準備完了になるまで待ってください。',SAVE_UNAVAILABLE:'セーブを確認できませんでした。通信を確認して再試行してください。',UNAUTHENTICATED:'ログイン情報を確認できませんでした。ログインし直してください。',STAGE_LOCKED:'ステージ1をクリアし、全員の探索終了を待ってください。',NEED_EXPLORER:'探索者が1人以上必要です。',RESUME_FAILED:'再接続できませんでした。ルームへ入り直してください。',INPUT_OVERFLOW:'通信の遅延が大きいため入力を再同期します。',NOT_CONNECTED:'再接続中の参加者がいます。'}
function connect(action,details={}){
 manualClose=false;network='接続中…';const url=endpoint.replace(/^http/,'ws')+'/socket';ws=new WebSocket(url)
 ws.onopen=async()=>{network='';try{if(['create','join'].includes(action)&&account?.user)details.idToken=await account.user.getIdToken();if(ws.readyState!==WebSocket.OPEN)return;ws.send(JSON.stringify({type:action,...details,protocol:PROTOCOL_VERSION}));reconnectAttempt=0}catch{tell('アカウントを確認できませんでした。ログインし直してください。');ws.close()}}
 ws.onmessage=event=>{try{const d=JSON.parse(event.data)
  if(d.type==='joined'){meId=d.id;mySessionId=d.id;token=d.token;roomCode=d.code;host=d.host;myRole=d.role==='monster'?'monster':'player';roleChoice=myRole;sessionStorage.setItem('shutter.role',myRole);sessionStorage.setItem('shutter.session',JSON.stringify({id:meId,token,code:roomCode,endpoint,role:myRole}));network=''}
  if(d.type==='lobby'){lobby=d;host=d.host;const self=d.members.find(m=>m.id===meId);if(self){myRole=self.role==='monster'?'monster':'player';roleChoice=myRole;sessionStorage.setItem('shutter.role',myRole)}if(mode==='lobby')render()}
  if(d.type==='start'){resultFinished=false;state=d.state;myRole=d.state.viewer?.role==='monster'?'monster':'player';roleChoice=myRole;lastTick=-1;lastEvent=state.eventId;const controlled=myEntity(state);seq=controlled?.ack||0;pending=[];predicted=controlled?structuredClone(controlled):null;if(predicted)predicted.kind=myRole==='monster'?'monster':'player';look={yaw:predicted?.yaw||0,pitch:predicted?.pitch||0};offset={x:0,y:0,z:0};snapshots=[];remoteBuffer.reset();outcomeShown=false;acc=0;if(action==='resume')go('pause');else go('instructions')}
  if(d.type==='state'&&d.state.tick>lastTick){lastTick=d.state.tick;const next=d.state,authoritative=myEntity(next);if(authoritative&&predicted){const before={x:predicted.x+offset.x,y:predicted.y+offset.y,z:predicted.z+offset.z};pending=pending.filter(c=>c.seq>authoritative.ack);predicted=structuredClone(authoritative);predicted.kind=myRole==='monster'?'monster':'player';const base=stagePlatforms(next),platforms=runtimePlatforms(base,next.traps,next.time,next.timedOut),walls=trapWalls(base,next.traps,next.time);for(const c of pending){if(myRole==='monster'){if(next.stage===2)moveStageTwoMonster(predicted,c,next.settings,stageSolids(next));else moveControlledMonster(predicted,c,next.settings,platforms)}else movePlayer(predicted,c,next.settings,next.open,platforms,walls,stageSolids(next))}const error=Math.hypot(before.x-predicted.x,before.y-predicted.y,before.z-predicted.z);offset=error<1.5?{x:before.x-predicted.x,y:before.y-predicted.y,z:before.z-predicted.z}:{x:0,y:0,z:0}}state=next;remoteBuffer.add(next,performance.now())}
  if(d.type==='pong')rtt=performance.now()-d.sent
  if(d.type==='error'){tell(networkErrors[d.code]||'通信処理に失敗しました。');if(['RESUME_FAILED','ROOM_NOT_FOUND'].includes(d.code)){manualClose=true;ws.close();sessionStorage.removeItem('shutter.session');state=null;lobby=null;go('lobby')}if(d.code==='INPUT_OVERFLOW'){ws.close()}}
 }catch{tell('通信データを読み取れませんでした。')}}
 ws.onclose=()=>{if(manualClose)return;network='接続が切れました。再接続中…';reconnectAt=performance.now()+1000;if(!state)tell('サーバーに接続できません。起動を少し待ち、もう一度試してください。')}
 ws.onerror=()=>{network='通信に接続できません。'}
}
function send(type,data={}){if(ws?.readyState===WebSocket.OPEN)ws.send(JSON.stringify({type,...data}));else tell('接続を確認してください。')}
function leave(){manualClose=true;if(ws?.readyState===WebSocket.OPEN)ws.send(JSON.stringify({type:'leave'}));ws?.close();ws=null;lobby=null;state=null;predicted=null;sessionStorage.removeItem('shutter.session');pending=[];network='';roomCode='';host=null}
function command(){const right=(keys.has('KeyD')?1:0)-(keys.has('KeyA')?1:0)+stick.right,forward=(keys.has('KeyW')?1:0)-(keys.has('KeyS')?1:0)+stick.forward,enabled=mode==='game'&&!sensitivityOpen;const c={seq:++seq,right:enabled?right:0,forward:enabled?forward:0,yaw:look.yaw,pitch:look.pitch,fov:config.fov,aspect:innerWidth/innerHeight,jump:myRole!=='monster'&&enabled&&jump,interact:myRole!=='monster'&&enabled&&interact};jump=false;interact=false;return c}
function updateHUD(){if(mode!=='game'||!state)return;const p=playType==='online'?predicted:state.players.find(p=>p.id===meId),hunter=myRole==='monster';const counter=root.querySelector('#lever-count');if(counter)counter.textContent=hunter?`${state.players.filter(p=>p.status==='active').length} VISIBLE`:state.levers.filter(Boolean).length+' / '+LEVERS.length;const timer=root.querySelector('#match-time'),remaining=Math.max(0,Math.ceil(MATCH_TIME_LIMIT-state.time));if(timer)timer.textContent=state.stage===2?formatTime(state.time):state.timedOut?'TIME OVER':`${Math.floor(remaining/60)}:${String(remaining%60).padStart(2,'0')}`;root.querySelector('.hud')?.classList.toggle('time-over',state.timedOut===true);const players=root.querySelector('#members-count'),summary=state.summary;if(players)players.textContent=playType==='online'?`${summary?.active??state.players.filter(p=>p.status==='active').length} / ${summary?.total??state.players.length} PLAYERS`:'';let text='';if(p&&!hunter){const base=stagePlatforms(state),platforms=runtimePlatforms(base,state.traps,state.time,state.timedOut),i=stageLevers(state).findIndex((l,i)=>!state.levers[i]&&canUseLever(p,l,platforms));if(i>=0)text='E　調べる';else if(Math.hypot(p.x-DOOR.x,p.z-DOOR.z)<3&&!state.open)text='E　調べる'}const target=root.querySelector('#interaction');if(hunter&&state.stage===2)text=p?.frozen?'見られている — 移動できない':'視線の外から追え';if(target)target.textContent=text;const n=root.querySelector('#network-status');if(n)n.textContent=network||(new URLSearchParams(location.search).has('debug')?`${Math.round(rtt)}ms · tick ${state.tick} · pending ${pending.length} · pos ${p?.x.toFixed(2)},${p?.y.toFixed(2)},${p?.z.toFixed(2)} · ${p?.surface||p?.mode} · buffer ${Math.round(remoteBuffer.delay)}ms`:'')}
