function handleEvents(){if(!state)return;if(state.players.some(p=>p.id===meId&&p.status==='escaped')||state.finished&&(state.summary?.escaped||state.players.some(p=>p.status==='escaped')||myRole==='monster'&&state.summary?.dead))account?.completeStage(state.stage||1);if(state.finished&&!resultFinished){resultFinished=true;if(['dead','clear','hunter-lose'].includes(mode))render()}for(const e of state.events||[]){if(e.id<=lastEvent)continue;lastEvent=e.id;if(e.type==='splash')view?.ripple(e.x,e.z);if(e.type!=='caught'||e.player!==meId)audio.event(e,state,meId);if(myRole==='monster'&&e.type==='splash')toast('水音を検知した');if(e.type==='timeout')toast('TIME OVER — 足場が沈む！');if(e.type==='trap')toast(e.trap==='shift'?'足場が横へ動いた！':'上から壁が落ちてくる！');if(e.type==='caught'&&e.player===meId&&myRole!=='monster'&&!outcomeShown&&view){startJumpscare()}}if(myRole==='monster'){if(state.finished&&!outcomeShown){outcomeShown=true;go(state.summary?.escaped?'hunter-lose':'hunter-win')}return}const p=state.players.find(p=>p.id===meId);if(p&&!outcomeShown&&['dead','escaped','left'].includes(p.status)){outcomeShown=true;go(p.status==='escaped'?'clear':'dead')}}
